    public Bitmap g1(RecyclerView recyclerView, LinearLayout linearLayout) {
        RecyclerView.Adapter adapter = recyclerView.getAdapter();
        int itemCount = adapter.getItemCount();
        ArrayList arrayList = new ArrayList();
        linearLayout.measure(View.MeasureSpec.makeMeasureSpec(linearLayout.getWidth(), 1073741824), View.MeasureSpec.makeMeasureSpec(0, 0));
        linearLayout.layout(0, 0, linearLayout.getMeasuredWidth(), linearLayout.getMeasuredHeight());
        linearLayout.setDrawingCacheEnabled(true);
        linearLayout.buildDrawingCache();
        arrayList.add(linearLayout.getDrawingCache());
        int measuredHeight = linearLayout.getMeasuredHeight();
        Log.d("trace_2Bitmap=", "" + itemCount);
        for (int i = 0; i < itemCount; i++) {
            RecyclerView.ViewHolder viewHolderCreateViewHolder = adapter.createViewHolder(recyclerView, adapter.getItemViewType(i));
            adapter.onBindViewHolder(viewHolderCreateViewHolder, i);
            View view = viewHolderCreateViewHolder.itemView;
            view.measure(View.MeasureSpec.makeMeasureSpec(recyclerView.getWidth(), 1073741824), View.MeasureSpec.makeMeasureSpec(0, 0));
            view.layout(0, 0, view.getMeasuredWidth(), view.getMeasuredHeight());
            view.setDrawingCacheEnabled(true);
            view.buildDrawingCache();
            Bitmap bitmapCreateBitmap = Bitmap.createBitmap(viewHolderCreateViewHolder.itemView.getWidth(), viewHolderCreateViewHolder.itemView.getHeight(), Bitmap.Config.RGB_565);
            Canvas canvas = new Canvas(bitmapCreateBitmap);
            canvas.drawColor(-1);
            viewHolderCreateViewHolder.itemView.draw(canvas);
            arrayList.add(bitmapCreateBitmap);
            measuredHeight += view.getMeasuredHeight();
        }
        Bitmap bitmapCreateBitmap2 = Bitmap.createBitmap(recyclerView.getMeasuredWidth(), measuredHeight, Bitmap.Config.RGB_565);
        Canvas canvas2 = new Canvas(bitmapCreateBitmap2);
        Paint paint = new Paint();
        int height = 0;
        for (int i2 = 0; i2 < arrayList.size(); i2++) {
            Bitmap bitmap = (Bitmap) arrayList.get(i2);
            canvas2.drawBitmap(bitmap, 0.0f, height, paint);
            height += bitmap.getHeight();
        }
        return bitmapCreateBitmap2;
    }

